from __future__ import annotations

import hmac
from dataclasses import dataclass

from lxml import etree

from .signature import XmlSignatureVerifier

SAML_PROTOCOL = "urn:oasis:names:tc:SAML:2.0:protocol"
SAML_ASSERTION = "urn:oasis:names:tc:SAML:2.0:assertion"
SUCCESS_STATUS = "urn:oasis:names:tc:SAML:2.0:status:Success"


class SamlParseError(ValueError):
    pass


@dataclass(frozen=True)
class LogoutResponse:
    response_id: str
    in_response_to: str
    issuer: str
    status_code: str


@dataclass(frozen=True)
class ValidationResult:
    accepted: bool
    reason: str
    response: LogoutResponse | None = None


def parse_logout_response(payload: bytes) -> LogoutResponse:
    """Parse a SAML LogoutResponse into its typed representation."""
    parser = etree.XMLParser(resolve_entities=False, no_network=True, remove_comments=False)
    try:
        root = etree.fromstring(payload, parser=parser)
    except etree.XMLSyntaxError as exc:
        raise SamlParseError("malformed_xml") from exc
    if root.tag != f"{{{SAML_PROTOCOL}}}LogoutResponse":
        raise SamlParseError("unexpected_root")
    issuer_node = root.find(f"{{{SAML_ASSERTION}}}Issuer")
    status_node = root.find(
        f"{{{SAML_PROTOCOL}}}Status/{{{SAML_PROTOCOL}}}StatusCode"
    )

    # TODO: extract required fields and return LogoutResponse.
    raise NotImplementedError("parse_logout_response is not implemented")


class LogoutResponseValidator:
    def __init__(
        self,
        trusted_issuer: str,
        signature_verifier: XmlSignatureVerifier,
    ):
        self._trusted_issuer = trusted_issuer
        self._signature_verifier = signature_verifier


    def validate(self, payload: bytes) -> ValidationResult:
        verified_payload = self._signature_verifier.verify(payload)
        if verified_payload is None:
            return ValidationResult(False, "invalid_signature")
        try:
            response = parse_logout_response(verified_payload)
        except SamlParseError as exc:
            return ValidationResult(False, str(exc))
        if not hmac.compare_digest(response.issuer, self._trusted_issuer):
            return ValidationResult(False, "untrusted_issuer", response)
        if response.status_code != SUCCESS_STATUS:
            return ValidationResult(False, "logout_failed", response)
        return ValidationResult(True, "accepted", response)

import unittest

from identity_gateway.saml import (
    LogoutResponseValidator,
    SamlParseError,
    parse_logout_response,
)
from identity_gateway.signature import XmlSignatureVerifier
from tests.fixtures import (
    TEST_CERT,
    TRUSTED_ISSUER,
    logout_response,
    signed_logout_response,
)


class LogoutResponseParserTests(unittest.TestCase):
    def test_extracts_required_fields(self):
        response = parse_logout_response(logout_response())
        self.assertEqual(response.response_id, "logout-response-001")
        self.assertEqual(response.in_response_to, "logout-request-123")
        self.assertEqual(response.issuer, TRUSTED_ISSUER)
        self.assertEqual(response.status_code, "urn:oasis:names:tc:SAML:2.0:status:Success")

    def test_rejects_unexpected_root(self):
        with self.assertRaisesRegex(SamlParseError, "unexpected_root"):
            parse_logout_response(b"<Response/>")

    def test_rejects_missing_required_field(self):
        payload = logout_response().replace(b' InResponseTo="logout-request-123"', b"")
        with self.assertRaisesRegex(SamlParseError, "missing_required_field"):
            parse_logout_response(payload)


class LogoutResponseValidatorTests(unittest.TestCase):
    def setUp(self):
        self.validator = LogoutResponseValidator(
            TRUSTED_ISSUER,
            XmlSignatureVerifier(TEST_CERT),
        )

    def test_accepts_valid_signed_response(self):
        self.assertTrue(self.validator.validate(signed_logout_response()).accepted)

    def test_rejects_unsigned_response(self):
        result = self.validator.validate(logout_response())
        self.assertFalse(result.accepted)
        self.assertEqual(result.reason, "invalid_signature")

    def test_rejects_signed_response_from_wrong_issuer(self):
        result = self.validator.validate(
            signed_logout_response(issuer="https://unknown.example/saml")
        )
        self.assertFalse(result.accepted)
        self.assertEqual(result.reason, "untrusted_issuer")

    def test_rejects_malformed_xml(self):
        self.assertFalse(self.validator.validate(b"<not-saml>").accepted)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

from pathlib import Path

from lxml import etree
from signxml import SignatureConfiguration, XMLVerifier
from signxml.exceptions import InvalidInput, InvalidSignature


class XmlSignatureVerifier:
    """Verify one enveloped XMLDSig document against a pinned IdP certificate."""

    def __init__(self, certificate_path: Path):
        self._certificate = certificate_path.read_bytes()
        self._configuration = SignatureConfiguration(
            location="./",
            expect_references=1,
        )

    def verify(self, payload: bytes) -> bytes | None:
        try:
            result = XMLVerifier().verify(
                payload,
                x509_cert=self._certificate,
                expect_config=self._configuration,
            )
        except (InvalidInput, InvalidSignature, etree.XMLSyntaxError, ValueError):
            return None
        return etree.tostring(result.signed_xml)

